def main():
    MOD = 1_000_000_007

    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])

    if M == 0:
        print(1)
        return

    broken_steps = set()
    for i in range(2, 2 + M):
        broken_steps.add(int(data[i]) - 1)  # convert to zero-based index

    dp = [0] * (N + 1)
    dp[0] = 1  # There's one way to stand at the ground (doing nothing)

    for i in range(1, N + 1):
        if i - 1 not in broken_steps:
            dp[i] = dp[i - 1]
        if i - 2 >= 0 and i - 2 not in broken_steps:
            dp[i] = (dp[i] + dp[i - 2]) % MOD

    print(dp[N])

if __name__ == "__main__":
    main()
